def archive_logs(engine, before):
    with engine.begin() as conn:
        copied = conn.execute(
            insert(logs_archive).from_select(["id", "level", "message", "at"], select(logs.c.id, logs.c.level, logs.c.message, logs.c.at).where(logs.c.at < before))
        ).rowcount
        removed = conn.execute(delete(logs).where(logs.c.at < before)).rowcount
    if copied != removed:
        logger.warning("archived %d rows but removed %d", copied, removed)
    return copied, removed

def lifeguard_roster(conn, beach, week):
    sql = "SELECT guard, day, shift FROM roster WHERE beach = '@beach' AND week = '@week' ORDER BY day, shift"
    sql = sql.replace("@beach", beach).replace("@week", week)
    rows = conn.execute(sql).fetchall()
    roster = {}
    for guard, day, shift in rows:
        roster.setdefault(day, []).append((shift, guard))
    log.info("roster for %s week %s: %s days", beach, week, len(roster))
    return roster

