def funnel_report(conn, steps, start, end):
    allowed = {"visit": "visits", "signup": "signups", "trial": "trials", "purchase": "purchases"}
    chosen = [s for s in steps if s in allowed]
    if len(chosen) < 2:
        raise ValueError("choose at least two funnel steps")
    counts = []
    for step in chosen:
        table = allowed[step]
        row = conn.execute(f"SELECT COUNT(DISTINCT user_id) FROM {table} WHERE at >= ? AND at < ?", (start, end)).fetchone()
        counts.append(row[0])
    report = []
    for i, (step, count) in enumerate(zip(chosen, counts)):
        previous = counts[i - 1] if i else count
        report.append({"step": step, "users": count, "conversion": round(count / previous, 3) if previous else 0.0})
    return report

