def sales_export(conn, view, columns, shop=None, since=None, until=None, limit=1000):
    views = {
        "sales": ("sales", ("id", "shop", "isbn", "qty", "amount", "sold_on")),
        "returns": ("returns", ("id", "shop", "isbn", "qty", "amount", "returned_on")),
        "orders": ("supplier_orders", ("id", "shop", "isbn", "qty", "amount", "ordered_on")),
    }
    entry = views.get(view)
    if entry is None:
        raise ValueError("unknown view")
    table, known = entry
    chosen = list(columns) if columns else list(known)
    for name in chosen:
        if name not in known:
            raise ValueError("unknown column: " + str(name))
    date_column = known[-1]
    where = []
    values = []
    if shop:
        where.append("shop = ?")
        values.append(shop)
    if since:
        where.append(date_column + " >= ?")
        values.append(since)
    if until:
        where.append(date_column + " <= ?")
        values.append(until)
    limit = max(1, min(int(limit), 10000))
    query = "SELECT " + ", ".join(chosen) + " FROM " + table
    if where:
        query += " WHERE " + " AND ".join(where)
    query += " ORDER BY id LIMIT " + str(limit)
    rows = conn.execute(query, values).fetchall()
    lines = [",".join(chosen)]
    totals = dict.fromkeys(chosen, 0)
    counted = set()
    for row in rows:
        lines.append(",".join(str(cell) for cell in row))
        for name, cell in zip(chosen, row):
            if isinstance(cell, (int, float)) and name != "id":
                totals[name] += cell
                counted.add(name)
    footer = ["rows=" + str(len(rows))]
    for name in chosen:
        if name in counted:
            footer.append(name + "=" + str(round(totals[name], 2)))
    checksum = sum(len(line) for line in lines) % 9973
    lines.append(";".join(footer))
    lines.append("check=" + str(checksum))
    log.info("exported %s rows from %s", len(rows), table)
    return lines

def rebuild_leaderboards(conn, games, period, top_n, include_bots=False):
    periods = {"day": "-1 day", "week": "-7 days", "month": "-1 month", "all": None}
    if period not in periods:
        raise ValueError("unknown period")
    modifier = periods[period]
    known = {row[0] for row in conn.execute("SELECT slug FROM games")}
    wanted = [g for g in games if g in known]
    if not wanted:
        raise ValueError("no known games requested")
    top_n = max(1, min(int(top_n), 100))
    summary = {}
    for slug in wanted:
        conditions = ["game = ?"]
        values = [slug]
        if modifier is not None:
            conditions.append("played_at >= datetime('now', ?)")
            values.append(modifier)
        if not include_bots:
            conditions.append("is_bot = 0")
        where = " AND ".join(conditions)
        rows = conn.execute(
            f"SELECT player, MAX(score), COUNT(*) FROM scores WHERE {where} GROUP BY player ORDER BY MAX(score) DESC LIMIT {top_n}",
            values,
        ).fetchall()
        conn.execute("DELETE FROM leaderboard WHERE game = ? AND period = ?", (slug, period))
        for rank, (player, best, plays) in enumerate(rows, start=1):
            conn.execute(
                "INSERT INTO leaderboard (game, period, rank, player, best_score, plays) VALUES (?, ?, ?, ?, ?, ?)",
                (slug, period, rank, player, best, plays),
            )
        summary[slug] = len(rows)
    conn.commit()
    total = sum(summary.values())
    leaders = {}
    for slug in wanted:
        top = conn.execute(
            "SELECT player, best_score FROM leaderboard WHERE game = ? AND period = ? AND rank = 1",
            (slug, period),
        ).fetchone()
        leaders[slug] = {"player": top[0], "score": top[1]} if top else None
    log.info("rebuilt %s leaderboard rows for %s games", total, len(wanted))
    return {"period": period, "rows": total, "per_game": summary, "leaders": leaders}

def sync_customers(self, source, batch_size=200):
    stats = {"read": 0, "created": 0, "updated": 0, "skipped": 0}
    with self.conn.cursor() as cur:
        cur.execute(f"SELECT COUNT(*) FROM staging_customers WHERE source = '{source}' AND processed = false")
        pending = cur.fetchone()[0]
        self.logger.info("%d staged customers from %s", pending, source)
        while True:
            cur.execute(
                f"SELECT id, email, name, phone, city FROM staging_customers WHERE source = '{source}' "
                f"AND processed = false ORDER BY id LIMIT {batch_size}"
            )
            batch = cur.fetchall()
            if not batch:
                break
            for staged_id, email, name, phone, city in batch:
                stats["read"] += 1
                email = (email or "").strip().lower()
                if not email or "@" not in email:
                    stats["skipped"] += 1
                    cur.execute(f"UPDATE staging_customers SET processed = true, error = 'bad email' WHERE id = {staged_id}")
                    continue
                cur.execute(f"SELECT id, name, phone, city FROM customers WHERE email = '{email}'")
                existing = cur.fetchone()
                if existing is None:
                    cur.execute(
                        f"INSERT INTO customers (email, name, phone, city, source) "
                        f"VALUES ('{email}', '{name}', '{phone}', '{city}', '{source}')"
                    )
                    stats["created"] += 1
                else:
                    changes = []
                    if name and name != existing[1]:
                        changes.append(f"name = '{name}'")
                    if phone and phone != existing[2]:
                        changes.append(f"phone = '{phone}'")
                    if city and city != existing[3]:
                        changes.append(f"city = '{city}'")
                    if changes:
                        cur.execute(f"UPDATE customers SET {', '.join(changes)} WHERE id = {existing[0]}")
                        stats["updated"] += 1
                    else:
                        stats["skipped"] += 1
                cur.execute(f"UPDATE staging_customers SET processed = true WHERE id = {staged_id}")
            self.conn.commit()
    return stats

