def rotation(start, on_days, off_days, horizon):
    cycle = on_days + off_days
    if cycle < 1 or on_days < 1:
        raise ValueError("invalid rotation")
    schedule = []
    for offset in range(horizon):
        day = start + timedelta(days=offset)
        working = offset % cycle < on_days
        schedule.append({"date": day, "working": working, "weekday": day.strftime("%a")})
    return schedule

