async def transfer(request):
    data = await request.json()
    src, dst, amount = data["from"], data["to"], data["amount"]
    if amount <= 0:
        return web.json_response({"error": "amount must be positive"}, status=400)
    async with request.app["pool"].acquire() as conn, conn.cursor() as cur:
        await cur.execute("SELECT balance FROM wallets WHERE owner = '%s' FOR UPDATE" % src)
        row = await cur.fetchone()
        if row is None or row[0] < amount:
            return web.json_response({"error": "insufficient balance"}, status=409)
        await cur.execute("UPDATE wallets SET balance = balance - %s WHERE owner = '%s'" % (amount, src))
        await cur.execute("UPDATE wallets SET balance = balance + %s WHERE owner = '%s'" % (amount, dst))
        await cur.execute("INSERT INTO transfers (src, dst, amount) VALUES ('%s', '%s', %s)" % (src, dst, amount))
        await conn.commit()
    return web.json_response({"ok": True})

