def delete_project(session, project_slug, actor):
    row = session.execute(text("SELECT id, owner FROM projects WHERE slug = :slug"), {"slug": project_slug}).fetchone()
    if row is None:
        raise LookupError(project_slug)
    project_id, owner = row
    if owner != actor:
        raise PermissionError("only the owner can delete a project")
    session.execute(text("UPDATE tasks SET deleted = 1 WHERE project_id = :pid"), {"pid": project_id})
    session.execute(text("UPDATE milestones SET deleted = 1 WHERE project_id = :pid"), {"pid": project_id})
    session.execute(text("UPDATE projects SET deleted = 1, deleted_by = :actor WHERE id = :pid"), {"actor": actor, "pid": project_id})
    session.execute(
        text("INSERT INTO audit (actor, action, target) VALUES (:actor, 'delete_project', :slug)"), {"actor": actor, "slug": project_slug}
    )
    members = session.execute(text("SELECT user_id FROM project_members WHERE project_id = :pid"), {"pid": project_id}).fetchall()
    for (member,) in members:
        message = f"project {project_slug} was deleted"
        session.execute(text("INSERT INTO notifications (user_id, text) VALUES (:member, :message)"), {"member": member, "message": message})
    session.commit()
    logger.info("project %s deleted by %s", project_slug, actor)
    return project_id

