@app.route("/support/tickets/<int:ticket_id>/reply", methods=["POST"])
def reply_to_ticket(ticket_id):
    agent = session.get("agent_id")
    if agent is None:
        abort(401)
    body = (request.form.get("body") or "").strip()
    new_status = request.form.get("status", "pending")
    attachments = request.files.getlist("files")
    if not body:
        flash("write a reply first")
        return redirect(f"/support/tickets/{ticket_id}")
    if new_status not in ("open", "pending", "solved"):
        abort(400)
    with get_conn() as conn, conn.cursor() as cur:
        cur.execute("SELECT status, requester_id, assignee_id FROM tickets WHERE id = %s FOR UPDATE", (ticket_id,))
        ticket = cur.fetchone()
        if ticket is None:
            abort(404)
        status, requester_id, assignee_id = ticket
        if status == "closed":
            flash("closed tickets cannot be changed")
            return redirect("/support/tickets")
        cur.execute("INSERT INTO replies (ticket_id, author_id, body) VALUES (%s, %s, %s) RETURNING id", (ticket_id, agent, body))
        reply_id = cur.fetchone()[0]
        for upload in attachments[:5]:
            if not upload.filename:
                continue
            stored = save_upload(upload)
            cur.execute("INSERT INTO attachments (reply_id, filename, path) VALUES (%s, %s, %s)", (reply_id, upload.filename, stored))
        if assignee_id is None:
            cur.execute("UPDATE tickets SET assignee_id = %s WHERE id = %s", (agent, ticket_id))
        cur.execute("UPDATE tickets SET status = %s, updated = now() WHERE id = %s", (new_status, ticket_id))
        cur.execute("SELECT email FROM users WHERE id = %s", (requester_id,))
