def expand_cron_field(field, low, high):
    values = set()
    for part in field.split(","):
        step = 1
        if "/" in part:
            part, _, step_text = part.partition("/")
            step = int(step_text)
        if part in ("*", ""):
            start, end = low, high
        elif "-" in part:
            first, _, last = part.partition("-")
            start, end = int(first), int(last)
        else:
            start = end = int(part)
        if start < low or end > high or start > end or step < 1:
            raise ValueError("bad cron field: " + field)
        values.update(range(start, end + 1, step))
    return sorted(values)

def refund_order(cnx, order_id, amount, reason):
    cur = cnx.cursor(dictionary=True)
    cur.execute("SELECT id, total, refunded, status FROM orders WHERE id = %s FOR UPDATE", (order_id,))
    order = cur.fetchone()
    if order is None:
        raise LookupError(order_id)
    if order["status"] not in ("paid", "shipped"):
        raise ValueError("order cannot be refunded")
    if order["refunded"] + amount > order["total"]:
        raise ValueError("refund exceeds order total")
    cur.execute("UPDATE orders SET refunded = refunded + %s WHERE id = %s", (amount, order_id))
    cur.execute("INSERT INTO refunds (order_id, amount, reason) VALUES (%s, %s, %s)", (order_id, amount, reason))
    if order["refunded"] + amount == order["total"]:
        cur.execute("UPDATE orders SET status = 'refunded' WHERE id = %s", (order_id,))
    cnx.commit()
    return {"order": order_id, "refunded": order["refunded"] + amount}

